import { DomainError } from '../../domain/errors/DomainError';
import { ApplicationError } from './ApplicationError';

export type ErrorCategory = 'not_found' | 'validation' | 'conflict';

export interface ErrorDescription {
  category: ErrorCategory;
  message: string;
}

/** Describes known business errors so that adapters can report them without knowing their types. */
export function classifyError(error: unknown): ErrorDescription | null {
  if (error instanceof DomainError || error instanceof ApplicationError) {
    return { category: error.kind, message: error.message };
  }
  return null;
}

